       detailedLogForPersistenceError(e);
       throw e;
     } finally {
-      //close the em if necessary
+      // close the em if necessary
       if (null != didWeStartWork.get()) {
         didWeStartWork.remove();
         unitOfWork.end();
       }
     }

-    //or return result
+    // or return result
